import{_ as i,o as a,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Alchemy","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/alchemy.md","filePath":"en/game-design/professions/alchemy.md"}'),t={name:"en/game-design/professions/alchemy.md"};function o(l,e,r,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="alchemy" tabindex="-1">Alchemy <a class="header-anchor" href="#alchemy" aria-label="Permalink to &quot;Alchemy&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Player-facing overview</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Alchemy should be based on simplified early-chemistry/alchemical processes, without becoming a chemistry simulator.</p><h3 id="core-operations" tabindex="-1">Core operations <a class="header-anchor" href="#core-operations" aria-label="Permalink to &quot;Core operations&quot;">​</a></h3><ul><li>Crush</li><li>Dissolve</li><li>Heat</li><li>Distill</li><li>Separate</li><li>Combine</li></ul><p>Materials contain discoverable principles/essences such as:</p><ul><li>Motive</li><li>Vital</li><li>Volatile</li><li>Combustive</li><li>Toxic</li><li>Somnolent</li><li>Purifying</li><li>etc.</li></ul><p>Exact naming is still design-level and can remain Proposed.</p><p>The system should emphasize principles/reactions, not only hardcoded potion recipes.</p><p>Example: Combustive + Volatile -&gt; explosive behavior. Vital + Restorative -&gt; regenerative preparation. Toxic + Penetrating -&gt; poison-like preparation.</p><h3 id="laboratory-equipment" tabindex="-1">Laboratory equipment <a class="header-anchor" href="#laboratory-equipment" aria-label="Permalink to &quot;Laboratory equipment&quot;">​</a></h3><ul><li>mortar and pestle;</li><li>vial;</li><li>burner;</li><li>crucible;</li><li>alembic/retort/condenser;</li><li>scales;</li><li>reaction vessels.</li></ul><h3 id="relevant-variables" tabindex="-1">Relevant variables <a class="header-anchor" href="#relevant-variables" aria-label="Permalink to &quot;Relevant variables&quot;">​</a></h3><ul><li>extraction medium/solvent;</li><li>heat state;</li><li>purity;</li><li>concentration;</li><li>stability.</li></ul><p>Do not overexpose exact chemistry-like numbers to players unless later justified.</p><h3 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h3><ul><li>draughts;</li><li>oils;</li><li>powders;</li><li>pastes;</li><li>salves;</li><li>toxins;</li><li>solvents;</li><li>reagents;</li><li>volatile mixtures;</li><li>inks;</li><li>preservatives.</li></ul><h3 id="pvp-and-pvm-utility" tabindex="-1">PvP and PvM utility <a class="header-anchor" href="#pvp-and-pvm-utility" aria-label="Permalink to &quot;PvP and PvM utility&quot;">​</a></h3><ul><li>explosion mixtures;</li><li>smoke;</li><li>irritants;</li><li>adhesives;</li><li>timed/delayed preparations;</li><li>poisons;</li><li>medical support.</li></ul><h3 id="localized-injury-interactions" tabindex="-1">Localized injury interactions <a class="header-anchor" href="#localized-injury-interactions" aria-label="Permalink to &quot;Localized injury interactions&quot;">​</a></h3><ul><li>coagulant reduces bleeding;</li><li>analgesic temporarily reduces pain penalties without healing trauma;</li><li>stimulant affects fatigue;</li><li>antidotes interact with toxin principles.</li></ul><p>Poison should eventually be richer than fixed Poison 1–5. Possible variables:</p><ul><li>toxicity;</li><li>onset;</li><li>duration/persistence;</li><li>delivery;</li><li>symptom families.</li></ul><p>Experimentation should create observations and new formulations.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Alchemical Journal.</strong> Distillation and Toxicology are example learned techniques; observations and reactions lead to formulations, not just recipe popups. Names and reaction examples remain provisional.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Alchemy can supply Tinkering payloads, Tailoring treatments/dyes, Carpentry treatments and medical preparations. Healing, local trauma, fatigue and magical Concentration require coordinated design rather than inferred effects.</p><p><a href="/Syrolands-Public/en/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/en/game-design/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/en/game-design/combat/damage.html">Local Trauma</a> · <a href="/Syrolands-Public/en/game-design/combat/future-directions.html">Future injury systems</a> · <a href="/Syrolands-Public/en/game-design/magic.html#meditation-and-concentration">Meditation and Concentration</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Essence taxonomy and reaction rules; extraction windows; qualitative disclosures; stability and storage; delivery, doses, stacking, counterplay and friendly fire; toxin onset/duration/symptoms; Healing and injury compatibility. The examples below do not establish bleeding, pain or poison redesign in the current slice.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p><h2 id="magic-materials-—-batch-04" tabindex="-1">Magic materials — Batch 04 <a class="header-anchor" href="#magic-materials-—-batch-04" aria-label="Permalink to &quot;Magic materials — Batch 04&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html#reagents-remain-physical-resources">Reagents</a> remain physical, generally lootable catalysts, stabilizers, carriers and components. Alchemy may prepare/process them for Core Patterns, modifiers and <a href="/Syrolands-Public/en/game-design/professions/inscription.html">Inscription</a>. This is Proposed: no reagent family, substitution formula, production dependency or runtime item change is finalized.</p>',40)])])}const u=i(t,[["render",o]]);export{m as __pageData,u as default};
